// ../sdk/src/model/procgen/buildGeometry/buildGrid.ts
function buildGrid(cfg) {
  let size = cfg.size || 1;
  if (size < 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildGrid] Negative size not allowed."
    };
  }
  let divisions = cfg.divisions || 1;
  if (divisions < 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildGrid] Negative divisions not allowed."
    };
  }
  if (divisions < 1) {
    divisions = 1;
  }
  const step2 = size / divisions;
  const halfSize = size / 2;
  const positions = [];
  const indices = [];
  let l = 0;
  for (let i = 0, k = -halfSize; i <= divisions; i++, k += step2) {
    positions.push(-halfSize, 0, k);
    positions.push(halfSize, 0, k);
    positions.push(k, 0, -halfSize);
    positions.push(k, 0, halfSize);
    indices.push(l++, l++, l++, l++);
  }
  const geometryArrays = apply(cfg, {
    primitive: "lines",
    positions,
    indices
  });
  return { ok: true, value: geometryArrays };
}

// ../sdk/src/model/procgen/buildGeometry/buildBoxLines.ts
function buildBoxLines(cfg = {
  center: [0, 0, 0],
  xSize: 1,
  ySize: 1,
  zSize: 1
}) {
  const center = cfg.center;
  if (center && center.length !== 3) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildBoxLines] Center must be a 3D point [x, y, z]."
    };
  }
  const xSize = cfg.xSize || 1;
  if (xSize < 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildBoxLines] Negative xSize not allowed."
    };
  }
  const ySize = cfg.ySize || 1;
  if (ySize < 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildBoxLines] Negative ySize not allowed."
    };
  }
  const zSize = cfg.zSize || 1;
  if (zSize < 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildBoxLines] Negative zSize not allowed."
    };
  }
  const centerX = center ? center[0] : 0;
  const centerY = center ? center[1] : 0;
  const centerZ = center ? center[2] : 0;
  const xmin = -xSize + centerX;
  const ymin = -ySize + centerY;
  const zmin = -zSize + centerZ;
  const xmax = xSize + centerX;
  const ymax = ySize + centerY;
  const zmax = zSize + centerZ;
  const geometryArrays = apply(cfg, {
    primitive: LinesPrimitive,
    // The positions represent the vertices of the box.
    // These are the 8 corner points of the box in 3D space.
    positions: [
      xmin,
      ymin,
      zmin,
      xmin,
      ymin,
      zmax,
      xmin,
      ymax,
      zmin,
      xmin,
      ymax,
      zmax,
      xmax,
      ymin,
      zmin,
      xmax,
      ymin,
      zmax,
      xmax,
      ymax,
      zmin,
      xmax,
      ymax,
      zmax
    ],
    // Indices define the lines that connect the vertices to form the wireframe.
    indices: [
      0,
      1,
      // line from v0 to v1
      1,
      3,
      // line from v1 to v3
      3,
      2,
      // line from v3 to v2
      2,
      0,
      // line from v2 to v0
      4,
      5,
      // line from v4 to v5
      5,
      7,
      // line from v5 to v7
      7,
      6,
      // line from v7 to v6
      6,
      4,
      // line from v6 to v4
      0,
      4,
      // line from v0 to v4
      1,
      5,
      // line from v1 to v5
      2,
      6,
      // line from v2 to v6
      3,
      7
      // line from v3 to v7
    ]
  });
  return { ok: true, value: geometryArrays };
}

// ../sdk/src/model/procgen/buildGeometry/buildCylinder.ts
function buildCylinder(cfg = {
  center: [0, 0, 0],
  radiusTop: 1,
  radiusBottom: 1,
  height: 1,
  radialSegments: 60,
  heightSegments: 1,
  openEnded: false
}) {
  const center = cfg.center || [0, 0, 0];
  const radiusTop = cfg.radiusTop ?? 1;
  const radiusBottom = cfg.radiusBottom ?? 1;
  const height = cfg.height ?? 1;
  const radialSegments = cfg.radialSegments ?? 60;
  const heightSegments = cfg.heightSegments ?? 1;
  const openEnded = cfg.openEnded ?? false;
  if (center.length !== 3) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildCylinder] Center must be a 3D point [x, y, z]."
    };
  }
  if (radiusTop < 0 || radiusBottom < 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildCylinder] Negative radius values are not allowed."
    };
  }
  if (height < 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildCylinder] Negative height is not allowed."
    };
  }
  if (radialSegments < 3) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildCylinder] radialSegments must be at least 3."
    };
  }
  if (heightSegments < 1) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildCylinder] heightSegments must be at least 1."
    };
  }
  const positions = [];
  const normals = [];
  const uvs = [];
  const indices = [];
  const halfHeight = height / 2;
  const stride = radialSegments + 1;
  for (let y = 0; y <= heightSegments; y++) {
    const v = y / heightSegments;
    const radius = v * (radiusBottom - radiusTop) + radiusTop;
    for (let x = 0; x <= radialSegments; x++) {
      const u = x / radialSegments;
      const theta = u * Math.PI * 2;
      const sinTheta = Math.sin(theta);
      const cosTheta = Math.cos(theta);
      const vertexX = radius * sinTheta;
      const vertexY = -v * height + halfHeight;
      const vertexZ = radius * cosTheta;
      positions.push(vertexX + center[0], vertexY + center[1], vertexZ + center[2]);
      normals.push(sinTheta, 0, cosTheta);
      uvs.push(u, 1 - v);
    }
  }
  for (let y = 1; y <= heightSegments; y++) {
    for (let x = 0; x < radialSegments; x++) {
      const a2 = (y - 1) * stride + x;
      const b4 = (y - 1) * stride + x + 1;
      const c2 = y * stride + x + 1;
      const d = y * stride + x;
      indices.push(a2, b4, d);
      indices.push(b4, c2, d);
    }
  }
  if (!openEnded) {
    const cap = (isTop) => {
      const sign = isTop ? 1 : -1;
      const radius = isTop ? radiusTop : radiusBottom;
      const centerIndex = positions.length / 3;
      positions.push(center[0], center[1] + sign * halfHeight, center[2]);
      normals.push(0, sign, 0);
      uvs.push(0.5, 0.5);
      for (let x = 0; x <= radialSegments; x++) {
        const theta = x / radialSegments * Math.PI * 2;
        const cosTheta = Math.cos(theta);
        const sinTheta = Math.sin(theta);
        positions.push(
          radius * sinTheta + center[0],
          center[1] + sign * halfHeight,
          radius * cosTheta + center[2]
        );
        normals.push(0, sign, 0);
        uvs.push((cosTheta + 1) / 2, (sinTheta + 1) / 2);
        if (x > 0) {
          const a2 = centerIndex;
          const b4 = centerIndex + x;
          const c2 = centerIndex + x + 1;
          if (isTop) {
            indices.push(a2, b4, c2);
          } else {
            indices.push(a2, c2, b4);
          }
        }
      }
    };
    cap(true);
    cap(false);
  }
  const geometryArrays = {
    primitive: TrianglesPrimitive,
    positions,
    normals,
    uv: uvs,
    indices
  };
  return { ok: true, value: geometryArrays };
}

// ../sdk/src/model/procgen/buildGeometry/buildExtrude.ts
function buildExtrude(cfg) {
  const shape = cfg.shape;
  const path = cfg.path;
  const closedShape = cfg.closedShape ?? true;
  const closedPath = cfg.closedPath ?? false;
  const wantCaps = (cfg.caps ?? true) && closedShape && !closedPath;
  if (!shape || shape.length < 6 || shape.length % 2 !== 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildExtrude] shape must be a flat 2D polygon with at least 3 vertices (length >= 6, even)."
    };
  }
  if (!path || path.length < 6 || path.length % 3 !== 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildExtrude] path must be a flat 3D polyline with at least 2 vertices (length >= 6, multiple of 3)."
    };
  }
  const shapeCount = shape.length / 2;
  const pathCount = path.length / 3;
  const tangents = new Float32Array(pathCount * 3);
  for (let i = 0; i < pathCount; i++) {
    let dx = 0, dy = 0, dz = 0;
    const iNext = i < pathCount - 1 ? i + 1 : closedPath ? 0 : -1;
    if (iNext >= 0) {
      dx += path[iNext * 3] - path[i * 3];
      dy += path[iNext * 3 + 1] - path[i * 3 + 1];
      dz += path[iNext * 3 + 2] - path[i * 3 + 2];
    }
    const iPrev = i > 0 ? i - 1 : closedPath ? pathCount - 1 : -1;
    if (iPrev >= 0) {
      dx += path[i * 3] - path[iPrev * 3];
      dy += path[i * 3 + 1] - path[iPrev * 3 + 1];
      dz += path[i * 3 + 2] - path[iPrev * 3 + 2];
    }
    const len = Math.hypot(dx, dy, dz) || 1;
    tangents[i * 3] = dx / len;
    tangents[i * 3 + 1] = dy / len;
    tangents[i * 3 + 2] = dz / len;
  }
  const T0x = tangents[0], T0y = tangents[1], T0z = tangents[2];
  let upX = 0, upY = 1, upZ = 0;
  if (Math.abs(T0x * upX + T0y * upY + T0z * upZ) > 0.95) {
    upX = 1;
    upY = 0;
    upZ = 0;
  }
  const dotUp0 = T0x * upX + T0y * upY + T0z * upZ;
  let N0x = upX - T0x * dotUp0;
  let N0y = upY - T0y * dotUp0;
  let N0z = upZ - T0z * dotUp0;
  const n0Len = Math.hypot(N0x, N0y, N0z) || 1;
  N0x /= n0Len;
  N0y /= n0Len;
  N0z /= n0Len;
  const Ns = new Float32Array(pathCount * 3);
  const Bs = new Float32Array(pathCount * 3);
  Ns[0] = N0x;
  Ns[1] = N0y;
  Ns[2] = N0z;
  Bs[0] = T0y * N0z - T0z * N0y;
  Bs[1] = T0z * N0x - T0x * N0z;
  Bs[2] = T0x * N0y - T0y * N0x;
  for (let i = 1; i < pathCount; i++) {
    const Tx = tangents[i * 3], Ty = tangents[i * 3 + 1], Tz = tangents[i * 3 + 2];
    let Nx = Ns[(i - 1) * 3];
    let Ny = Ns[(i - 1) * 3 + 1];
    let Nz = Ns[(i - 1) * 3 + 2];
    const dotTN = Tx * Nx + Ty * Ny + Tz * Nz;
    Nx -= Tx * dotTN;
    Ny -= Ty * dotTN;
    Nz -= Tz * dotTN;
    const nLen = Math.hypot(Nx, Ny, Nz) || 1;
    Nx /= nLen;
    Ny /= nLen;
    Nz /= nLen;
    Ns[i * 3] = Nx;
    Ns[i * 3 + 1] = Ny;
    Ns[i * 3 + 2] = Nz;
    Bs[i * 3] = Ty * Nz - Tz * Ny;
    Bs[i * 3 + 1] = Tz * Nx - Tx * Nz;
    Bs[i * 3 + 2] = Tx * Ny - Ty * Nx;
  }
  const shapeNormals = new Float32Array(shapeCount * 2);
  for (let j = 0; j < shapeCount; j++) {
    const jPrev = j > 0 ? j - 1 : closedShape ? shapeCount - 1 : 0;
    const jNext = j < shapeCount - 1 ? j + 1 : closedShape ? 0 : shapeCount - 1;
    const eInY = shape[j * 2 + 1] - shape[jPrev * 2 + 1];
    const eInX = shape[j * 2] - shape[jPrev * 2];
    const eOutY = shape[jNext * 2 + 1] - shape[j * 2 + 1];
    const eOutX = shape[jNext * 2] - shape[j * 2];
    const nx = eInY + eOutY;
    const ny = -(eInX + eOutX);
    const len = Math.hypot(nx, ny) || 1;
    shapeNormals[j * 2] = nx / len;
    shapeNormals[j * 2 + 1] = ny / len;
  }
  const shapeUs = new Float32Array(shapeCount);
  let shapePerim = 0;
  shapeUs[0] = 0;
  for (let j = 1; j < shapeCount; j++) {
    const dx = shape[j * 2] - shape[(j - 1) * 2];
    const dy = shape[j * 2 + 1] - shape[(j - 1) * 2 + 1];
    shapeUs[j] = shapeUs[j - 1] + Math.hypot(dx, dy);
  }
  if (closedShape) {
    const dx = shape[0] - shape[(shapeCount - 1) * 2];
    const dy = shape[1] - shape[(shapeCount - 1) * 2 + 1];
    shapePerim = shapeUs[shapeCount - 1] + Math.hypot(dx, dy);
  } else {
    shapePerim = shapeUs[shapeCount - 1];
  }
  if (shapePerim === 0)
    shapePerim = 1;
  const pathVs = new Float32Array(pathCount);
  pathVs[0] = 0;
  for (let i = 1; i < pathCount; i++) {
    const dx = path[i * 3] - path[(i - 1) * 3];
    const dy = path[i * 3 + 1] - path[(i - 1) * 3 + 1];
    const dz = path[i * 3 + 2] - path[(i - 1) * 3 + 2];
    pathVs[i] = pathVs[i - 1] + Math.hypot(dx, dy, dz);
  }
  let pathLen = pathVs[pathCount - 1];
  if (closedPath) {
    const dx = path[0] - path[(pathCount - 1) * 3];
    const dy = path[1] - path[(pathCount - 1) * 3 + 1];
    const dz = path[2] - path[(pathCount - 1) * 3 + 2];
    pathLen += Math.hypot(dx, dy, dz);
  }
  if (pathLen === 0)
    pathLen = 1;
  const positions = [];
  const normals = [];
  const uv = [];
  for (let i = 0; i < pathCount; i++) {
    const Px = path[i * 3], Py = path[i * 3 + 1], Pz = path[i * 3 + 2];
    const Nx = Ns[i * 3], Ny = Ns[i * 3 + 1], Nz = Ns[i * 3 + 2];
    const Bx = Bs[i * 3], By = Bs[i * 3 + 1], Bz = Bs[i * 3 + 2];
    const v = pathVs[i] / pathLen;
    for (let j = 0; j < shapeCount; j++) {
      const sx = shape[j * 2];
      const sy = shape[j * 2 + 1];
      positions.push(
        Px + Nx * sx + Bx * sy,
        Py + Ny * sx + By * sy,
        Pz + Nz * sx + Bz * sy
      );
      const sn2x = shapeNormals[j * 2];
      const sn2y = shapeNormals[j * 2 + 1];
      normals.push(
        Nx * sn2x + Bx * sn2y,
        Ny * sn2x + By * sn2y,
        Nz * sn2x + Bz * sn2y
      );
      uv.push(shapeUs[j] / shapePerim, v);
    }
  }
  const indices = [];
  const segCountPath = closedPath ? pathCount : pathCount - 1;
  const segCountShape = closedShape ? shapeCount : shapeCount - 1;
  for (let i = 0; i < segCountPath; i++) {
    const i0 = i;
    const i1 = (i + 1) % pathCount;
    for (let j = 0; j < segCountShape; j++) {
      const j0 = j;
      const j1 = (j + 1) % shapeCount;
      const a2 = i0 * shapeCount + j0;
      const b4 = i0 * shapeCount + j1;
      const c2 = i1 * shapeCount + j1;
      const d = i1 * shapeCount + j0;
      indices.push(a2, b4, c2, a2, c2, d);
    }
  }
  if (wantCaps) {
    {
      const baseIdx = positions.length / 3;
      const Px = path[0], Py = path[1], Pz = path[2];
      const Nx = Ns[0], Ny = Ns[1], Nz = Ns[2];
      const Bx = Bs[0], By = Bs[1], Bz = Bs[2];
      const Tx = tangents[0], Ty = tangents[1], Tz = tangents[2];
      for (let j = 0; j < shapeCount; j++) {
        const sx = shape[j * 2];
        const sy = shape[j * 2 + 1];
        positions.push(
          Px + Nx * sx + Bx * sy,
          Py + Ny * sx + By * sy,
          Pz + Nz * sx + Bz * sy
        );
        normals.push(-Tx, -Ty, -Tz);
        uv.push(0.5 + sx * 0.5, 0.5 + sy * 0.5);
      }
      for (let j = 1; j < shapeCount - 1; j++) {
        indices.push(baseIdx, baseIdx + j + 1, baseIdx + j);
      }
    }
    {
      const last = pathCount - 1;
      const baseIdx = positions.length / 3;
      const Px = path[last * 3], Py = path[last * 3 + 1], Pz = path[last * 3 + 2];
      const Nx = Ns[last * 3], Ny = Ns[last * 3 + 1], Nz = Ns[last * 3 + 2];
      const Bx = Bs[last * 3], By = Bs[last * 3 + 1], Bz = Bs[last * 3 + 2];
      const Tx = tangents[last * 3], Ty = tangents[last * 3 + 1], Tz = tangents[last * 3 + 2];
      for (let j = 0; j < shapeCount; j++) {
        const sx = shape[j * 2];
        const sy = shape[j * 2 + 1];
        positions.push(
          Px + Nx * sx + Bx * sy,
          Py + Ny * sx + By * sy,
          Pz + Nz * sx + Bz * sy
        );
        normals.push(Tx, Ty, Tz);
        uv.push(0.5 + sx * 0.5, 0.5 + sy * 0.5);
      }
      for (let j = 1; j < shapeCount - 1; j++) {
        indices.push(baseIdx, baseIdx + j, baseIdx + j + 1);
      }
    }
  }
  return {
    ok: true,
    value: {
      primitive: TrianglesPrimitive,
      positions,
      normals,
      uv,
      indices
    }
  };
}

// ../sdk/src/model/procgen/buildGeometry/buildLathe.ts
function buildLathe(cfg) {
  const profile = cfg.profile;
  const segments = Math.max(3, Math.floor(cfg.segments ?? 32));
  const closedProfile = cfg.closedProfile ?? false;
  if (!profile || profile.length < 4 || profile.length % 2 !== 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildLathe] profile must be a flat 2D path with at least 2 vertices (length >= 4, even)."
    };
  }
  const profCount = profile.length / 2;
  const segCount = segments + 1;
  const profNormals = new Float32Array(profCount * 2);
  for (let i = 0; i < profCount; i++) {
    const iPrev = i > 0 ? i - 1 : closedProfile ? profCount - 1 : 0;
    const iNext = i < profCount - 1 ? i + 1 : closedProfile ? 0 : profCount - 1;
    const dInR = profile[i * 2] - profile[iPrev * 2];
    const dInY = profile[i * 2 + 1] - profile[iPrev * 2 + 1];
    const dOutR = profile[iNext * 2] - profile[i * 2];
    const dOutY = profile[iNext * 2 + 1] - profile[i * 2 + 1];
    const nr = dInY + dOutY;
    const ny = -(dInR + dOutR);
    const len = Math.hypot(nr, ny) || 1;
    profNormals[i * 2] = nr / len;
    profNormals[i * 2 + 1] = ny / len;
  }
  const profVs = new Float32Array(profCount);
  profVs[0] = 0;
  for (let i = 1; i < profCount; i++) {
    const dr = profile[i * 2] - profile[(i - 1) * 2];
    const dy = profile[i * 2 + 1] - profile[(i - 1) * 2 + 1];
    profVs[i] = profVs[i - 1] + Math.hypot(dr, dy);
  }
  let profLen = profVs[profCount - 1];
  if (closedProfile) {
    const dr = profile[0] - profile[(profCount - 1) * 2];
    const dy = profile[1] - profile[(profCount - 1) * 2 + 1];
    profLen += Math.hypot(dr, dy);
  }
  if (profLen === 0)
    profLen = 1;
  const positions = [];
  const normals = [];
  const uv = [];
  const TWO_PI = Math.PI * 2;
  for (let i = 0; i < profCount; i++) {
    const r = profile[i * 2];
    const y = profile[i * 2 + 1];
    const nr = profNormals[i * 2];
    const ny = profNormals[i * 2 + 1];
    const v = profVs[i] / profLen;
    for (let s = 0; s < segCount; s++) {
      const angle2 = s / segments * TWO_PI;
      const cos = Math.cos(angle2);
      const sin = Math.sin(angle2);
      positions.push(r * cos, y, r * sin);
      normals.push(nr * cos, ny, nr * sin);
      uv.push(s / segments, v);
    }
  }
  const indices = [];
  const ringSegCount = closedProfile ? profCount : profCount - 1;
  for (let i = 0; i < ringSegCount; i++) {
    const i0 = i;
    const i1 = (i + 1) % profCount;
    for (let s = 0; s < segments; s++) {
      const a2 = i0 * segCount + s;
      const b4 = i0 * segCount + s + 1;
      const c2 = i1 * segCount + s + 1;
      const d = i1 * segCount + s;
      indices.push(a2, b4, c2, a2, c2, d);
    }
  }
  return {
    ok: true,
    value: {
      primitive: TrianglesPrimitive,
      positions,
      normals,
      uv,
      indices
    }
  };
}

// ../sdk/src/model/procgen/buildGeometry/buildSphere.ts
function buildSphere(cfg = {
  heightSegments: 18,
  widthSegments: 18,
  radius: 1,
  center: [0, 0, 0]
}) {
  const center = cfg.center;
  if (center && center.length !== 3) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildSphere] Center must be a 3D point [x, y, z]."
    };
  }
  const centerX = center ? center[0] : 0;
  const centerY = center ? center[1] : 0;
  const centerZ = center ? center[2] : 0;
  let radius = cfg.radius || 1;
  if (radius < 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildSphere] Negative radius not allowed."
    };
  }
  let heightSegments = cfg.heightSegments || 18;
  if (heightSegments < 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildSphere] Negative heightSegments not allowed."
    };
  }
  heightSegments = Math.floor(heightSegments);
  if (heightSegments < 18) {
    heightSegments = 18;
  }
  let widthSegments = cfg.widthSegments || 18;
  if (widthSegments < 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildSphere] Negative widthSegments not allowed."
    };
  }
  widthSegments = Math.floor(widthSegments);
  if (widthSegments < 18) {
    widthSegments = 18;
  }
  const positions = [];
  const normals = [];
  const uvs = [];
  const indices = [];
  for (let i = 0; i <= heightSegments; i++) {
    const theta = i * Math.PI / heightSegments;
    const sinTheta = Math.sin(theta);
    const cosTheta = Math.cos(theta);
    for (let j = 0; j <= widthSegments; j++) {
      const phi = j * 2 * Math.PI / widthSegments;
      const sinPhi = Math.sin(phi);
      const cosPhi = Math.cos(phi);
      const x = cosPhi * sinTheta;
      const y = cosTheta;
      const z = sinPhi * sinTheta;
      const u = j / widthSegments;
      const v = i / heightSegments;
      positions.push(radius * x + centerX, radius * y + centerY, radius * z + centerZ);
      normals.push(x, y, z);
      uvs.push(u, v);
    }
  }
  for (let i = 0; i < heightSegments; i++) {
    for (let j = 0; j < widthSegments; j++) {
      const first = i * (widthSegments + 1) + j;
      const second = first + widthSegments + 1;
      indices.push(first, first + 1, second);
      indices.push(first + 1, second + 1, second);
    }
  }
  const geometryArrays = apply(cfg, {
    primitive: TrianglesPrimitive,
    positions,
    normals,
    uv: uvs,
    indices
  });
  return { ok: true, value: geometryArrays };
}

// ../sdk/src/model/procgen/buildGeometry/buildTorus.ts
function buildTorus(cfg = {
  radius: 0,
  tube: 0,
  radialSegments: 0,
  tubeSegments: 0,
  arc: 0,
  center: [0, 0, 0]
}) {
  let radius = cfg.radius || 1;
  if (radius < 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildTorus] Negative radius not allowed."
    };
  }
  radius *= 0.5;
  let tube = cfg.tube || 0.3;
  if (tube < 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildTorus] Negative tube not allowed."
    };
  }
  let radialSegments = cfg.radialSegments || 32;
  if (radialSegments < 4) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildTorus] radialSegments must be at least 4."
    };
  }
  let tubeSegments = cfg.tubeSegments || 24;
  if (tubeSegments < 4) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildTorus] tubeSegments must be at least 4."
    };
  }
  let arc = cfg.arc || Math.PI * 2;
  if (arc <= 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildTorus] Arc must be greater than 0."
    };
  }
  const center = cfg.center || [0, 0, 0];
  if (center.length !== 3) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildTorus] Center must be a 3D point [x, y, z]."
    };
  }
  const centerX = center[0];
  const centerY = center[1];
  const centerZ = center[2];
  const positions = [];
  const normals = [];
  const uvs = [];
  const indices = [];
  for (let j = 0; j <= tubeSegments; j++) {
    for (let i = 0; i <= radialSegments; i++) {
      const u = i / radialSegments * arc;
      const v = j / tubeSegments * Math.PI * 2;
      const x = (radius + tube * Math.cos(v)) * Math.cos(u);
      const y = (radius + tube * Math.cos(v)) * Math.sin(u);
      const z = tube * Math.sin(v);
      positions.push(x + centerX, y + centerY, z + centerZ);
      const vec = subVec3([x, y, z], [radius * Math.cos(u), radius * Math.sin(u), 0]);
      normals.push(...normalizeVec3(vec));
      uvs.push(i / radialSegments, j / tubeSegments);
    }
  }
  for (let j = 1; j <= tubeSegments; j++) {
    for (let i = 1; i <= radialSegments; i++) {
      const a2 = (radialSegments + 1) * j + i - 1;
      const b4 = (radialSegments + 1) * (j - 1) + i - 1;
      const c2 = (radialSegments + 1) * (j - 1) + i;
      const d = (radialSegments + 1) * j + i;
      indices.push(a2, b4, d);
      indices.push(b4, c2, d);
    }
  }
  const geometryArrays = apply(cfg, {
    primitive: TrianglesPrimitive,
    positions,
    normals,
    uv: uvs,
    indices
  });
  return { ok: true, value: geometryArrays };
}

