function buildVectorText(cfg = {
  origin: [0, 0, 0],
  size: 1,
  text: ""
}) {
  const origin2 = cfg.origin || [0, 0, 0];
  if (origin2.length !== 3) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildVectorText] Origin must be a 3D point (array of 3 numbers)."
    };
  }
  const size = cfg.size || 1;
  if (size <= 0) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildVectorText] Size must be a positive non-zero number."
    };
  }
  if (!cfg.text) {
    return {
      ok: false,
      type: 2 /* InvalidInput */,
      error: "[buildVectorText] Text string is required."
    };
  }
  const xOrigin = origin2[0];
  const yOrigin = origin2[1];
  const zOrigin = origin2[2];
  const positions = [];
  const indices = [];
  let text = cfg.text;
  if (isNumeric(text)) {
    text = "" + text;
  }
  const lines = (text || "").split("\n");
  let countVerts = 0;
  let y = 0;
  let x;
  let str;
  let len;
  let c2;
  const mag = 1 / 25;
  let penUp;
  let p1;
  let p2;
  let needLine;
  let pointsLen;
  let a2;
  for (let iLine = 0; iLine < lines.length; iLine++) {
    x = 0;
    str = lines[iLine];
    len = str.length;
    for (let i = 0; i < len; i++) {
      c2 = letters[str.charAt(i)];
      if (c2 === "\n") {
        continue;
      }
      if (!c2) {
        continue;
      }
      penUp = 1;
      p1 = -1;
      p2 = -1;
      needLine = false;
      pointsLen = c2.points.length;
      for (let j = 0; j < pointsLen; j++) {
        a2 = c2.points[j];
        if (a2[0] === -1 && a2[1] === -1) {
          penUp = 1;
          needLine = false;
          continue;
        }
        positions.push(x + a2[0] * size * mag + xOrigin);
        positions.push(y + a2[1] * size * mag + yOrigin);
        positions.push(0 + zOrigin);
        if (p1 === -1) {
          p1 = countVerts;
        } else if (p2 === -1) {
          p2 = countVerts;
        } else {
          p1 = p2;
          p2 = countVerts;
        }
        countVerts++;
        if (penUp) {
          penUp = false;
        } else {
          indices.push(p1);
          indices.push(p2);
        }
        needLine = true;
      }
      x += c2.width * mag * size;
    }
    y -= 35 * mag * size;
  }
  return {
    ok: true,
    value: apply(cfg, {
      primitive: LinesPrimitive,
      // The geometry is constructed as wireframe lines
      positions,
      indices
    })
  };
}

