      const r = baseColor[0] + (n - 0.5) * 0.05;
      const g = baseColor[1] + (n - 0.5) * 0.04;
      const b4 = baseColor[2] + (n - 0.5) * 0.04;
      const i = (y * size + x) * 4;
      cd[i] = Math.round(clamp01(r) * 255);
      cd[i + 1] = Math.round(clamp01(g) * 255);
