  s.verticesBase         = t0.r;
  s.indicesBase          = t0.g;
  s.edgeIndicesBase      = t0.b;
  s.normalsBase          = t0.a;
  s.uvsBase              = t1.r;
  s.polylineCumDistBase  = t1.g;
