    const v010 = d[off(ix0, iy1, iz0) + c2];
    const v110 = d[off(ix1, iy1, iz0) + c2];
    const v001 = d[off(ix0, iy0, iz1) + c2];
    const v101 = d[off(ix1, iy0, iz1) + c2];
    const v011 = d[off(ix0, iy1, iz1) + c2];
    const v111 = d[off(ix1, iy1, iz1) + c2];
    const v00 = v000 * (1 - tx) + v100 * tx;
    const v01 = v001 * (1 - tx) + v101 * tx;
    const v10 = v010 * (1 - tx) + v110 * tx;
    const v11 = v011 * (1 - tx) + v111 * tx;
    const v0 = v00 * (1 - ty) + v10 * ty;
    const v1 = v01 * (1 - ty) + v11 * ty;
