    const heightPx = AXIS_HEIGHT_PX + rowCount * taskRowHeight + 6;
    this._innerLeftPx = LEFT_GUTTER_PX;
    this._innerWidthPx = widthPx - LEFT_GUTTER_PX - RIGHT_PAD_PX;
    this._innerHeightPx = heightPx;
